class Solution {
public:
    int shortestBridge(vector<vector<int>>& grid) {
        int n = grid.size();
        queue<pair<int, int>> q;
        bool found = false;
        auto dfs = [&](auto& self, int r, int c) -> void {
            if (r < 0 || r >= n || c < 0 || c >= n || grid[r][c] != 1) return;
            grid[r][c] = 2;
            q.push({r, c});
            self(self, r + 1, c);
            self(self, r - 1, c);
            self(self, r, c + 1);
            self(self, r, c - 1);
        };
        for (int r = 0; r < n && !found; ++r) {
            for (int c = 0; c < n && !found; ++c) {
                if (grid[r][c] == 1) {
                    dfs(dfs, r, c);
                    found = true;
                }
            }
        }
        int steps = 0;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.empty()) {
            int sz = q.size();
            while (sz--) {
                auto [r, c] = q.front(); q.pop();
                for (auto& d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                        if (grid[nr][nc] == 1) return steps;
                        if (grid[nr][nc] == 0) {
                            grid[nr][nc] = 2;
                            q.push({nr, nc});
                        }
                    }
                }
            }
            ++steps;
        }
        return steps;
    }
};

class Solution {
    public int shortestBridge(int[][] grid) {
        int n = grid.length;
        Queue<int[]> q = new LinkedList<>();
        boolean found = false;
        for (int r = 0; r < n && !found; r++) {
            for (int c = 0; c < n && !found; c++) {
                if (grid[r][c] == 1) {
                    dfs(grid, r, c, n, q);
                    found = true;
                }
            }
        }
        int steps = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        while (!q.isEmpty()) {
            int sz = q.size();
            while (sz-- > 0) {
                int[] cur = q.poll();
                int r = cur[0], c = cur[1];
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                        if (grid[nr][nc] == 1) return steps;
                        if (grid[nr][nc] == 0) {
                            grid[nr][nc] = 2;
                            q.add(new int[]{nr, nc});
                        }
                    }
                }
            }
            steps++;
        }
        return steps;
    }
    private void dfs(int[][] g, int r, int c, int n, Queue<int[]> q) {
        if (r < 0 || r >= n || c < 0 || c >= n || g[r][c] != 1) return;
        g[r][c] = 2;
        q.add(new int[]{r, c});
        dfs(g, r + 1, c, n, q);
        dfs(g, r - 1, c, n, q);
        dfs(g, r, c + 1, n, q);
        dfs(g, r, c - 1, n, q);
    }
}

var shortestBridge = function(grid) {
    const n = grid.length;
    const q = [];
    let found = false;
    function dfs(r, c) {
        if (r < 0 || r >= n || c < 0 || c >= n || grid[r][c] !== 1) return;
        grid[r][c] = 2;
        q.push([r, c]);
        dfs(r + 1, c);
        dfs(r - 1, c);
        dfs(r, c + 1);
        dfs(r, c - 1);
    }
    for (let r = 0; r < n && !found; r++) {
        for (let c = 0; c < n && !found; c++) {
            if (grid[r][c] === 1) {
                dfs(r, c);
                found = true;
            }
        }
    }
    let steps = 0;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let head = 0;
    while (head < q.length) {
        const sz = q.length - head;
        for (let i = 0; i < sz; i++) {
            const [r, c] = q[head++];
            for (const [dr, dc] of dirs) {
                const nr = r + dr, nc = c + dc;
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    if (grid[nr][nc] === 1) return steps;
                    if (grid[nr][nc] === 0) {
                        grid[nr][nc] = 2;
                        q.push([nr, nc]);
                    }
                }
            }
        }
        steps++;
    }
    return steps;
};
